    def fail(msg):
        raise RulesFileError(f"{path}:{line}: {msg}")

    category, rtype = values["category"], values["type"]
    pattern, prio = values["pattern"], values["priority"]
    if not category:
        fail("empty category")
    if rtype not in ("contains", "regex"):
        fail(f"invalid type '{rtype}'")
    if not pattern:
        fail("empty pattern")
    if not re.fullmatch(r"-?[0-9]+", prio):
        fail(f"invalid priority '{prio}'")
    try:
        priority = int(prio)
    except ValueError:
        fail(f"invalid priority '{prio}'")
    compiled = None
    if rtype == "regex":
        try:
            compiled = re.compile(pattern, re.IGNORECASE)
        except re.error:
            fail(f"invalid regex '{pattern}'")
    return Rule(category, rtype, pattern, priority, compiled)


def load_rules(path):
    if path is None:
        return []
    return read_table(
        path, ("category", "type", "pattern", "priority"), RulesFileError, _parse_row
    )


def categorize(rules, description):
    folded = description.casefold()
    best = None
    for rule in rules:
        if rule.type == "contains":
            hit = rule.pattern.casefold() in folded
        else:
            hit = rule.compiled.search(description) is not None
        if hit and (best is None or rule.priority > best.priority):
            best = rule
    return best.category if best else "Uncategorized"

