# Interface:
#   aggregate(items) -> list[MonthGroup]
#     items: iterable of (Transaction, category). Returns months sorted by
#     code point; each MonthGroup has .month ("YYYY-MM"), .count, .income,
#     .expenses, .net (unrounded Decimals) and .categories (list of
#     CategoryEntry with .category/.count/.income/.expenses/.net, sorted).
#     Pass the result to render.render_report(groups, fmt).
import decimal
from dataclasses import dataclass, field
from decimal import Decimal

from csvledger.transactions import decimal_context


@dataclass
class CategoryEntry:
    category: str
    count: int = 0
    income: Decimal = Decimal(0)
    expenses: Decimal = Decimal(0)
    net: Decimal = Decimal(0)


@dataclass
class MonthGroup:
    month: str
    count: int = 0
    income: Decimal = Decimal(0)
    expenses: Decimal = Decimal(0)
    net: Decimal = Decimal(0)
    categories: list = field(default_factory=list)


def _digits(amount):
    t = amount.as_tuple()
    return len(t.digits) + abs(t.exponent)


def aggregate(items):
    items = list(items)
    # Wide enough to hold the integer and fractional spans of any sum exactly.
    digits = 2 * max((_digits(tx.amount) for tx, _ in items), default=0)
    cells = {}
    with decimal.localcontext(decimal_context(digits)):
        for tx, category in items:
            key = (tx.date.strftime("%Y-%m"), category)
            cell = cells.setdefault(key, CategoryEntry(category))
            cell.count += 1
            if tx.amount > 0:
                cell.income += tx.amount
            elif tx.amount < 0:
                cell.expenses += tx.amount
        groups = {}
        for (month, _), cell in sorted(cells.items()):
            cell.net = cell.income + cell.expenses
            g = groups.setdefault(month, MonthGroup(month))
            g.count += cell.count
            g.income += cell.income
            g.expenses += cell.expenses
            g.categories.append(cell)
        for g in groups.values():
            g.net = g.income + g.expenses
    return list(groups.values())
# Interface:
#   format_money(value: Decimal) -> str
#   render_report(groups, fmt) -> str      groups from report.aggregate(items)
#   render_categorize(items, fmt) -> str   items: iterable of (Transaction, category),
#                                          any order (sorted here by date, stable)
#   fmt is "table" or "json". Results end with "\n".
import decimal
import json
from decimal import Decimal

_CENT = Decimal("0.01")


def format_money(value):
    ctx = decimal.Context(
        prec=len(value.as_tuple().digits) + abs(value.as_tuple().exponent) + 10,
        rounding=decimal.ROUND_HALF_UP,
        traps=[decimal.InvalidOperation],
    )
    q = value.quantize(_CENT, context=ctx)
    if q == 0:
        return "0.00"
    return format(q, "f")


def _table(headers, aligns, rows):
    widths = [
        max(len(h), *(len(r[i]) for r in rows)) if rows else len(h)
        for i, h in enumerate(headers)
    ]

    def line(cells):
        parts = [
            c.rjust(w) if a == "R" else c.ljust(w)
            for c, w, a in zip(cells, widths, aligns)
        ]
        return "  ".join(parts).rstrip() + "\n"

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(r) for r in rows)
    return "".join(out)


def _json(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def _money_fields(e):
    return {
        "count": e.count,
        "income": format_money(e.income),
        "expenses": format_money(e.expenses),
        "net": format_money(e.net),
    }


def render_report(groups, fmt):
    if fmt == "json":
        months = []
        for g in groups:
            d = {"month": g.month, **_money_fields(g)}
            d["categories"] = [
                {"category": c.category, **_money_fields(c)} for c in g.categories
            ]
            months.append(d)
        return _json({"months": months})
    rows = [
        [g.month, c.category, str(c.count), format_money(c.income),
         format_money(c.expenses), format_money(c.net)]
        for g in groups
        for c in g.categories
    ]
    return _table(
        ["MONTH", "CATEGORY", "COUNT", "INCOME", "EXPENSES", "NET"],
        "LLRRRR",
        rows,
    )


def render_categorize(items, fmt):
    items = sorted(items, key=lambda it: it[0].date)
    if fmt == "json":
        return _json({"transactions": [
            {"date": tx.date.isoformat(), "description": tx.description,
             "amount": format_money(tx.amount), "category": cat}
            for tx, cat in items
        ]})
    rows = [
        [tx.date.isoformat(), format_money(tx.amount), cat, tx.description]
        for tx, cat in items
    ]
    return _table(["DATE", "AMOUNT", "CATEGORY", "DESCRIPTION"], "LRLL", rows)

